350	package net.officefloor.hq.app.person;
351	
352	import java.time.LocalDate;
353	import java.util.ArrayList;
354	import java.util.Comparator;
355	import java.util.HashMap;
356	import java.util.List;
357	import java.util.Map;
358	import java.util.Locale;
359	import java.util.function.Function;
360	import java.util.stream.Collectors;
361	import net.officefloor.hq.app.Audit;
362	import net.officefloor.hq.app.rollup.RollupService;
363	import net.officefloor.hq.app.sheet.SheetService;
364	import org.springframework.dao.DataIntegrityViolationException;
365	import org.springframework.http.HttpStatus;
366	import org.springframework.orm.ObjectOptimisticLockingFailureException;
367	import org.springframework.stereotype.Service;
368	import org.springframework.transaction.annotation.Transactional;
369	import org.springframework.web.server.ResponseStatusException;
370	
371	@Service
372	public class PersonService {
373	
374	    /** A person's statements: how many were taken, and the last one (null: none). */
375	    public record Statements(int count, Statement last) {
376	        public static final Statements NONE = new Statements(0, null);
377	    }
378	
379	    /** A patron as a person's row shows them: their id and name. */
380	    public record PatronOf(long id, String name) {}
381	
382	    private final PersonRepository people;
383	    private final StatementRepository statements;
384	    private final PatronRepository patrons;
385	    private final SheetService sheets;
386	    private final RollupService rollups;
387	    private final Audit audit;
388	
389	    public PersonService(PersonRepository people, StatementRepository statements, PatronRepository patrons,
390	            SheetService sheets, RollupService rollups, Audit audit) {
391	        this.people = people;
392	        this.statements = statements;
393	        this.patrons = patrons;
394	        this.sheets = sheets;
395	        this.rollups = rollups;
396	        this.audit = audit;
397	    }
398	
399	    /** The sheet's people, in the order they were added. */
400	    @Transactional(readOnly = true)
401	    public List<Person> list(String sheetId) {
402	        return people.findBySheetIdOrderByIdAsc(sheetId);
403	    }
404	
405	    /** Each person's statements on the sheet, by person id; a person with none is absent. */
406	    @Transactional(readOnly = true)
407	    public Map<Long, Statements> statements(String sheetId) {
408	        Map<Long, Statements> out = new HashMap<>();
409	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
410	            out.merge(s.getPersonId(), new Statements(1, s), (was, now) -> new Statements(was.count() + 1, s));
411	        }
412	        return out;
413	    }
414	
415	    /** Each person's patrons on the sheet, sorted by name, by person id; a person with none is absent. */
416	    @Transactional(readOnly = true)
417	    public Map<Long, List<PatronOf>> patrons(String sheetId) {
418	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
419	                .collect(Collectors.toMap(Person::getId, Function.identity()));
420	        Map<Long, List<PatronOf>> out = new HashMap<>();
421	        for (Patron link : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
422	            Person patron = byId.get(link.getPatronId());
423	            if (patron == null) continue;
424	            out.computeIfAbsent(link.getPersonId(), id -> new ArrayList<>())
425	                    .add(new PatronOf(patron.getId(), patron.getName()));
426	        }
427	        out.values().forEach(list -> list.sort(Comparator.comparing(PatronOf::name)));
428	        return out;
429	    }
430	
431	    /**
432	     * Name another person on the sheet as a person's patron: refused for the person themselves and for
433	     * one already named.
434	     */
435	    @Transactional
436	    public Person addPatron(String sheetId, String user, long personId, long patronId) {
437	        sheets.lock(sheetId, user);
438	        Person person = people.findByIdAndSheetId(personId, sheetId)
439	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
440	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
441	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron"));
442	        if (person.getId().equals(patron.getId())) {
443	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron");
444	        }
445	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) throw patronNamed();
446	        try {
447	            patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
448	        } catch (DataIntegrityViolationException e) {
449	            throw patronNamed();
450	        }
451	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
452	                + " name=" + person.getName() + " patron=" + patron.getName());
453	        return person;
454	    }
455	
456	    /** Add a person (the sheet is started when it was never loaded before). */
457	    @Transactional
458	    public Person add(String sheetId, String user, String name, Grade grade) {
459	        sheets.load(sheetId, user);
460	        String trimmed = name.trim();
461	        requireUnusedName(sheetId, null, trimmed);
462	        RollupService.Rollup before = rollups.snapshot(sheetId);
463	        Person saved;
464	        try {
465	            saved = people.saveAndFlush(new Person(sheetId, trimmed, grade));
466	        } catch (DataIntegrityViolationException e) {
467	            throw nameInUse();
468	        }
469	        audit(sheetId, user, "PERSON_ADDED", saved, grade);
470	        rollups.recordChanges(sheetId, user, before);
471	        return saved;
472	    }
473	
474	    /**
475	     * Change a person's name, and give them a grade from a date (the sheet's today when none is given),
476	     * keeping the grades already recorded; from the version of them the editor loaded: refused when
477	     * someone else has saved them since.
478	     */
479	    @Transactional
480	    public Person edit(String sheetId, String user, long personId, long version, String name, Grade grade,
481	            LocalDate gradeFrom) {
482	        Person person = people.findByIdAndSheetId(personId, sheetId)
483	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
484	        if (person.getVersion() != version) throw editedMeanwhile();
485	        String trimmed = name.trim();
486	        requireUnusedName(sheetId, personId, trimmed);
487	        RollupService.Rollup before = rollups.snapshot(sheetId);
488	        person.setName(trimmed);
489	        person.setGradeFrom(grade, gradeFrom != null ? gradeFrom : sheets.today(sheetId));
490	        Person saved;
491	        try {
492	            saved = people.saveAndFlush(person);
493	        } catch (ObjectOptimisticLockingFailureException e) {
494	            throw editedMeanwhile();
495	        } catch (DataIntegrityViolationException e) {
496	            throw nameInUse();
497	        }
498	        audit(sheetId, user, "PERSON_EDITED", saved, grade);
499	        rollups.recordChanges(sheetId, user, before);
500	        return saved;
501	    }
502	
503	    /** Retire a person from a date (the sheet's today when none is given). */
504	    @Transactional
505	    public Person retire(String sheetId, String user, long personId, LocalDate from) {
506	        sheets.lock(sheetId, user);
507	        Person person = people.findByIdAndSheetId(personId, sheetId)
508	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
509	        LocalDate dated = from != null ? from : sheets.today(sheetId);
510	        person.setRetiredFrom(dated);
511	        Person saved = people.saveAndFlush(person);
512	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
513	                + " name=" + saved.getName() + " from=" + dated);
514	        return saved;
515	    }
516	
517	    /**
518	     * Put a person on hold, or release them when held. Followed by the rollup lines of the figures it
519	     * moves (their open claims leave, or rejoin, the live totals).
520	     */
521	    @Transactional
522	    public Person toggleHold(String sheetId, String user, long personId) {
523	        sheets.lock(sheetId, user);
524	        Person person = people.findByIdAndSheetId(personId, sheetId)
525	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
526	        RollupService.Rollup before = rollups.snapshot(sheetId);
527	        person.setHeld(!person.isHeld());
528	        Person saved = people.saveAndFlush(person);
529	        audit.recordOnCommit((saved.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + sheetId
530	                + " by=" + user + " name=" + saved.getName());
531	        rollups.recordChanges(sheetId, user, before);
532	        return saved;
533	    }
534	
535	    private void audit(String sheetId, String user, String event, Person person, Grade grade) {
536	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
537	                + " name=" + person.getName() + " grade=" + grade);
538	    }
539	
540	    /** Refuse a name another person on the sheet already has, ignoring case. */
541	    private void requireUnusedName(String sheetId, Long personId, String name) {
542	        String key = name.toLowerCase(Locale.ROOT);
543	        boolean used = people.findBySheetIdOrderByIdAsc(sheetId).stream()
544	                .anyMatch(p -> !p.getId().equals(personId) && p.getName().toLowerCase(Locale.ROOT).equals(key));
545	        if (used) throw nameInUse();
546	    }
547	
548	    private static ResponseStatusException editedMeanwhile() {
549	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Someone else has saved this person since");
550	    }
551	
552	    private static ResponseStatusException patronNamed() {
553	        return new ResponseStatusException(HttpStatus.CONFLICT, "That patron is already named");
554	    }
555	
556	    private static ResponseStatusException nameInUse() {
557	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use");
558	    }
559	}
