632	package net.officefloor.hq.app.rollup;
633	
634	import java.math.BigDecimal;
635	import java.math.RoundingMode;
636	import java.time.LocalDate;
637	import java.time.temporal.ChronoUnit;
638	import java.util.ArrayList;
639	import java.util.LinkedHashMap;
640	import java.util.List;
641	import java.util.Map;
642	import java.util.Objects;
643	import java.util.stream.Collectors;
644	import net.officefloor.hq.app.Audit;
645	import net.officefloor.hq.app.claim.Claim;
646	import net.officefloor.hq.app.claim.ClaimRepository;
647	import net.officefloor.hq.app.claim.ClaimStatus;
648	import net.officefloor.hq.app.person.Person;
649	import net.officefloor.hq.app.person.PersonRepository;
650	import net.officefloor.hq.app.rate.Rate;
651	import net.officefloor.hq.app.rate.RateRepository;
652	import net.officefloor.hq.app.sheet.Sheet;
653	import net.officefloor.hq.app.sheet.SheetRepository;
654	import org.springframework.stereotype.Service;
655	import org.springframework.transaction.annotation.Transactional;
656	
657	/**
658	 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
659	 * claimed-total and due-total. A change takes a snapshot before it and, once its own audit lines are
660	 * written, records a ROLLUP line per person whose figures moved and a TOTALS line when the totals did.
661	 */
662	@Service
663	public class RollupService {
664	
665	    /** A person's figures, as text with two decimals; the due-total is "n/a" when they have none. */
666	    public record Figures(String name, String claimed, String dueTotal) {}
667	
668	    /** Each person's figures by id, in the order they were added, and the sheet's totals. */
669	    public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}
670	
671	    private final PersonRepository people;
672	    private final ClaimRepository claims;
673	    private final RateRepository rates;
674	    private final SheetRepository sheets;
675	    private final Audit audit;
676	
677	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
678	            SheetRepository sheets, Audit audit) {
679	        this.people = people;
680	        this.claims = claims;
681	        this.rates = rates;
682	        this.sheets = sheets;
683	        this.audit = audit;
684	    }
685	
686	    /**
687	     * The sheet's figures now. Only open and settled claims count (a held person's open ones do not); a person's due-total is the sum of
688	     * their figures (those with one), n/a when the grade in force on the sheet's today has no rate in
689	     * force then and no counting claim of theirs has a figure.
690	     */
691	    @Transactional(readOnly = true)
692	    public Rollup snapshot(String sheetId) {
693	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElseGet(LocalDate::now);
694	        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
695	                .filter(c -> c.getStatus().counts())
696	                .collect(Collectors.groupingBy(Claim::getPersonId));
697	        Map<Long, Figures> out = new LinkedHashMap<>();
698	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
699	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
700	        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
701	            List<Claim> counted = byPerson.getOrDefault(p.getId(), List.of()).stream()
702	                    .filter(c -> counts(p, c))
703	                    .toList();
704	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
705	            BigDecimal due = BigDecimal.ZERO.setScale(2);
706	            boolean anyFigure = false;
707	            for (Claim c : counted) {
708	                claimed = claimed.add(c.getAmount());
709	                BigDecimal figure = figure(sheetId, p, c);
710	                if (figure != null) due = due.add(figure);
711	                anyFigure |= figure != null;
712	            }
713	            boolean rated = rates.findInForce(sheetId, p.gradeOn(today), today).isPresent();
714	            claimedTotal = claimedTotal.add(claimed);
715	            if (rated || anyFigure) dueTotal = dueTotal.add(due);
716	            out.put(p.getId(), new Figures(p.getName(), text(claimed), rated || anyFigure ? text(due) : "n/a"));
717	        }
718	        return new Rollup(out, text(claimedTotal), text(dueTotal));
719	    }
720	
721	    /**
722	     * Whether a claim counts in the live totals: open and settled claims do, except the open claims
723	     * of a person on hold.
724	     */
725	    public static boolean counts(Person person, Claim claim) {
726	        return claim.getStatus().counts() && !(person.isHeld() && claim.getStatus() == ClaimStatus.OPEN);
727	    }
728	
729	    /**
730	     * Record, once the change commits, a ROLLUP line for each person whose figures moved since
731	     * {@code before} (a person who did not exist then counts as moved), then a TOTALS line when the
732	     * sheet's totals moved.
733	     */
734	    @Transactional(readOnly = true)
735	    public void recordChanges(String sheetId, String user, Rollup before) {
736	        Rollup after = snapshot(sheetId);
737	        List<String> lines = new ArrayList<>();
738	        after.people().forEach((id, now) -> {
739	            Figures was = before.people().get(id);
740	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
741	                lines.add("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
742	                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal());
743	            }
744	        });
745	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
746	                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
747	            lines.add("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
748	                    + " due-total=" + after.dueTotal());
749	        }
750	        lines.forEach(audit::recordOnCommit);
751	    }
752	
753	    /**
754	     * The figure a claim shows: a settled claim's fixed due (any late charge frozen in), else its
755	     * bound figure (see {@link #boundFigure}) with, when it is overdue, its late charge on top; null
756	     * when none.
757	     */
758	    @Transactional(readOnly = true)
759	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
760	        if (claim.getDue() != null) return claim.getDue();
761	        BigDecimal figure = boundFigure(sheetId, person, claim);
762	        if (figure == null || claim.isCorrection()) return figure;
763	        return sheets.findById(sheetId)
764	                .map(sheet -> figure.add(lateCharge(sheet, claim, figure, rounding(sheet, claim))))
765	                .orElse(figure);
766	    }
767	
768	    /**
769	     * The figure a statement binds a live claim to, without any late charge: the figure its person's
770	     * last statement bound it to, else its amount times the rate in force on its date for the grade
771	     * in force on its date (rounded as {@link #rounding} says), raised to the sheet's floor (a
772	     * correction has no floor); null when none.
773	     */
774	    @Transactional(readOnly = true)
775	    public BigDecimal boundFigure(String sheetId, Person person, Claim claim) {
776	        if (claim.isStated()) return claim.getStatedDue();
777	        Sheet sheet = sheets.findById(sheetId).orElse(null);
778	        BigDecimal floor = claim.isCorrection() ? null : sheet == null ? BigDecimal.ZERO : sheet.getFloor();
779	        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN : rounding(sheet, claim);
780	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
781	                .map(rate -> due(claim.getAmount(), rate, rounding))
782	                .map(due -> (floor == null ? due : due.max(floor)).setScale(2))
783	                .orElse(null);
784	    }
785	
786	    /**
787	     * An overdue claim's late charge on a figure: the sheet's late percent of it for every full 30
788	     * days the claim is overdue (open, due by its date plus the terms, before the sheet's today),
789	     * rounded like due; zero when it is not overdue.
790	     */
791	    private static BigDecimal lateCharge(Sheet sheet, Claim claim, BigDecimal figure, RoundingMode rounding) {
792	        if (claim.getStatus() != ClaimStatus.OPEN) return BigDecimal.ZERO;
793	        long daysOver = ChronoUnit.DAYS.between(claim.getDate().plusDays(sheet.getTerms()), sheet.getToday());
794	        if (daysOver <= 0) return BigDecimal.ZERO;
795	        BigDecimal pct = sheet.getLatePct().multiply(BigDecimal.valueOf(daysOver / 30));
796	        return figure.multiply(pct).movePointLeft(2).setScale(2, rounding);
797	    }
798	
799	    /**
800	     * How a claim's live figures round: half up when it is dated before the sheet's policy date (its
801	     * today when none is set), else half to even. A correction rounds by the date of the claim it
802	     * corrects (its own when that is not found).
803	     */
804	    private RoundingMode rounding(Sheet sheet, Claim claim) {
805	        LocalDate dated = claim.getDate();
806	        if (claim.getCorrects() != null) {
807	            dated = claims.findBySheetIdOrderByIdDesc(sheet.getId()).stream()
808	                    .filter(c -> c.getPersonId().equals(claim.getPersonId())
809	                            && claim.getCorrects().equals(c.getNumber()) && !c.getId().equals(claim.getId()))
810	                    .map(Claim::getDate)
811	                    .findFirst()
812	                    .orElse(dated);
813	        }
814	        return dated.isBefore(sheet.policyDateInForce()) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
815	    }
816	
817	    /** The amount times the rate's percent, rounded to cents as given (as the screen works it out). */
818	    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
819	        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, rounding);
820	    }
821	
822	    private static String text(BigDecimal amount) {
823	        return amount.setScale(2).toPlainString();
824	    }
825	}
