package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.session.SessionController;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /**
     * A person, with how many statements were taken for them and the last one's due-total (text with
     * two decimals, "n/a" when it had none) and date; both null before their first statement. The grade
     * is the one in force on the sheet's today; the grades are all they were given, by from-date.
     */
    public record PersonView(long id, String name, Grade grade, long version, int statementCount,
            String statedTotal, LocalDate statementDate, LocalDate retiredFrom, boolean held,
            List<PersonService.PatronOf> patrons, List<GradeView> grades) {
        static PersonView of(Person person, PersonService.Statements statements,
                List<PersonService.PatronOf> patrons, LocalDate today) {
            Statement last = statements.last();
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today), person.getVersion(),
                    statements.count(), last == null ? null
                            : last.getDueTotal() == null ? "n/a" : last.getDueTotal().setScale(2).toPlainString(),
                    last == null ? null : last.getTakenOn(), person.getRetiredFrom(), person.isHeld(), patrons,
                    person.getGrades().stream().map(g -> new GradeView(g.getGrade(), g.getFromDate())).toList());
        }
    }

    /** A grade a person was given, from a date (null: from the beginning of time). */
    public record GradeView(Grade grade, LocalDate from) {}

    /**
     * The version is the one the editor loaded; required to edit, ignored when adding. An edit gives the
     * grade from the grade-from date (the sheet's today when none); the first grade, when adding, applies
     * from the beginning of time.
     */
    public record PersonForm(@NotBlank @Size(max = 200) String name, @NotNull Grade grade, Long version,
            LocalDate gradeFrom) {}

    /** The date a person is retired from; without one, the sheet's today. */
    public record RetireForm(LocalDate from) {}

    /** The person to name as a patron. */
    public record PatronForm(@NotNull Long patronId) {}

    private final PersonService service;
    private final SheetService sheets;

    public PersonController(PersonService service, SheetService sheets) {
        this.service = service;
        this.sheets = sheets;
    }

    /** The sheet's people, in the order they were added. */
    @GetMapping
    public List<PersonView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user) {
        Map<Long, PersonService.Statements> statements = service.statements(sheetId);
        Map<Long, List<PersonService.PatronOf>> patrons = service.patrons(sheetId);
        LocalDate today = sheets.today(sheetId);
        return service.list(sheetId).stream()
                .map(p -> PersonView.of(p, statements.getOrDefault(p.getId(), PersonService.Statements.NONE),
                        patrons.getOrDefault(p.getId(), List.of()), today))
                .toList();
    }

    /** Add a person. */
    @PostMapping
    public PersonView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @Valid @RequestBody PersonForm form) {
        return view(sheetId, service.add(sheetId, user, form.name(), form.grade()));
    }

    /** Change a person's name and grade, refused when someone else saved them since that version. */
    @PutMapping("/{personId}")
    public PersonView edit(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @Valid @RequestBody PersonForm form) {
        if (form.version() == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The version being edited is required");
        }
        return view(sheetId, service.edit(sheetId, user, personId, form.version(), form.name(), form.grade(),
                form.gradeFrom()));
    }

    /** Retire a person from a date. */
    @PostMapping("/{personId}/retire")
    public PersonView retire(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @RequestBody(required = false) RetireForm form) {
        return view(sheetId, service.retire(sheetId, user, personId, form == null ? null : form.from()));
    }

    /** Put a person on hold, or take them off hold when they are held. */
    @PostMapping("/{personId}/hold")
    public PersonView hold(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user) {
        return view(sheetId, service.toggleHold(sheetId, user, personId));
    }

    /** Name another person on the sheet as the person's patron. */
    @PostMapping("/{personId}/patrons")
    public PersonView addPatron(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @Valid @RequestBody PatronForm form) {
        return view(sheetId, service.addPatron(sheetId, user, personId, form.patronId()));
    }

    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person,
                service.statements(sheetId).getOrDefault(person.getId(), PersonService.Statements.NONE),
                service.patrons(sheetId).getOrDefault(person.getId(), List.of()), sheets.today(sheetId));
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

/** A person on a sheet. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades they were given, each from its date; the first one from the beginning of time. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    /** Retired from this date (claims dated after it are refused); null when not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** On hold: their open claims count in no live total (settled ones still do). */
    @Column(name = "held", nullable = false)
    private boolean held;

    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {}

    public Person(String sheetId, String name, Grade grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new GradeFrom(grade, null));
    }

    public Long getId() { return id; }

    public long getVersion() { return version; }

    public String getSheetId() { return sheetId; }

    public String getName() { return name; }

    public void setName(String name) { this.name = name; }

    /** The grades they were given, by from-date (the one from the beginning of time first). */
    public List<GradeFrom> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(GradeFrom::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** The grade in force on {@code date}: the one with the latest from-date on or before it. */
    public Grade gradeOn(LocalDate date) {
        return grades.stream()
                .filter(g -> g.appliesOn(date))
                .max(Comparator.comparing(GradeFrom::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(GradeFrom::getGrade)
                .orElseThrow();
    }

    /** Give them a grade from a date, replacing the one they had from that date; the others are kept. */
    public void setGradeFrom(Grade grade, LocalDate from) {
        grades.removeIf(g -> Objects.equals(g.getFromDate(), from));
        grades.add(new GradeFrom(grade, from));
    }

    public LocalDate getRetiredFrom() { return retiredFrom; }

    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }

    public boolean isHeld() { return held; }

    public void setHeld(boolean held) { this.held = held; }

    /** Whether a claim dated {@code date} is after their retirement. */
    public boolean retiredOn(LocalDate date) { return retiredFrom != null && date.isAfter(retiredFrom); }
}
