182	
183	import java.math.BigDecimal;
184	import java.time.LocalDate;
185	import java.util.List;
186	import java.util.Locale;
187	import java.util.Map;
188	import java.util.function.Function;
189	import java.util.stream.Collectors;
190	import net.officefloor.hq.app.Audit;
191	import net.officefloor.hq.app.claim.Claim;
192	import net.officefloor.hq.app.claim.ClaimRepository;
193	import net.officefloor.hq.app.person.Person;
194	import net.officefloor.hq.app.person.PersonRepository;
195	import net.officefloor.hq.app.rollup.RollupService;
196	import net.officefloor.hq.app.settings.Role;
197	import net.officefloor.hq.app.settings.SettingsService;
198	import net.officefloor.hq.app.sheet.SheetService;
199	import org.springframework.dao.DataIntegrityViolationException;
200	import org.springframework.http.HttpStatus;
201	import org.springframework.stereotype.Service;
202	import org.springframework.transaction.annotation.Transactional;
203	import org.springframework.web.server.ResponseStatusException;
204	
205	@Service
206	public class PeriodService {
207	
208	    private final PeriodRepository periods;
209	    private final ClaimRepository claims;
210	    private final PersonRepository people;
211	    private final RollupService rollups;
212	    private final SheetService sheets;
213	    private final SettingsService settings;
214	    private final Audit audit;
215	
216	    public PeriodService(PeriodRepository periods, ClaimRepository claims, PersonRepository people,
217	            RollupService rollups, SheetService sheets, SettingsService settings, Audit audit) {
218	        this.periods = periods;
219	        this.claims = claims;
220	        this.people = people;
221	        this.rollups = rollups;
222	        this.sheets = sheets;
223	        this.settings = settings;
224	        this.audit = audit;
225	    }
226	
227	    /** The sheet's periods, by from-date. */
228	    @Transactional(readOnly = true)
229	    public List<Period> list(String sheetId) {
230	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
231	    }
232	
233	    /**
234	     * Add a period: refused when its to-date is before its from-date, when another period of the sheet
235	     * has its name (ignoring case), or when it shares a date with another. The sheet is locked so two
236	     * additions are checked one at a time (and is started when it was never loaded before).
237	     */
238	    @Transactional
239	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
240	        sheets.lock(sheetId, user);
241	        String trimmed = name.trim();
242	        if (to.isBefore(from)) {
243	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts");
244	        }
245	        List<Period> all = periods.findBySheetIdOrderByFromDateAsc(sheetId);
246	        String key = trimmed.toLowerCase(Locale.ROOT);
247	        if (all.stream().anyMatch(p -> p.getName().toLowerCase(Locale.ROOT).equals(key))) throw nameInUse();
248	        if (all.stream().anyMatch(p -> p.overlaps(from, to))) {
249	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another");
250	        }
251	        Period saved;
252	        try {
253	            saved = periods.saveAndFlush(new Period(sheetId, trimmed, from, to));
254	        } catch (DataIntegrityViolationException e) {
255	            throw nameInUse();
256	        }
257	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user
258	                + " period=" + saved.getName() + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
259	        return saved;
260	    }
261	
262	    /**
263	     * Close a period, fixing its due-total now: the sum of the figures (those with one) of the open and
264	     * settled claims dated in it (not a held person's open ones). A period already closed is refused.
265	     */
266	    @Transactional
267	    public Period close(String sheetId, String user, long periodId) {
268	        sheets.lock(sheetId, user);
269	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
270	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
271	        if (period.isClosed()) {
272	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
273	        }
274	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
275	                .collect(Collectors.toMap(Person::getId, Function.identity()));
276	        BigDecimal total = BigDecimal.ZERO.setScale(2);
277	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
278	            Person person = byId.get(c.getPersonId());
279	            if (person == null || !RollupService.counts(person, c) || !period.contains(c.getDate())) continue;
280	            BigDecimal figure = rollups.figure(sheetId, person, c);
281	            if (figure != null) total = total.add(figure);
282	        }
283	        period.close(total);
284	        Period saved = periods.saveAndFlush(period);
285	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user
286	                + " period=" + saved.getName() + " total=" + total.toPlainString());
287	        return saved;
288	    }
289	
290	    /**
291	     * Reopen a closed period, making its due-total live again. Only a steward can; anyone else, or a
292	     * period that is not closed, is refused.
293	     */
294	    @Transactional
295	    public Period reopen(String sheetId, String user, long periodId) {
296	        sheets.lock(sheetId, user);
297	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
298	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
299	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
300	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can reopen a period");
301	        }
302	        if (!period.isClosed()) {
303	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed");
304	        }
305	        period.reopen();
306	        Period saved = periods.saveAndFlush(period);
307	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
308	        return saved;
309	    }
310	
311	    /** Refuse a change to a claim dated {@code date} when a closed period of the sheet contains it. */
312	    @Transactional(readOnly = true)
313	    public void requireOpenOn(String sheetId, LocalDate date) {
314	        if (periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
315	                .anyMatch(p -> p.isClosed() && p.contains(date))) {
316	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated in a closed period");
317	        }
318	    }
319	
320	    private static ResponseStatusException nameInUse() {
321	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use");
322	    }
323	}
