713	     * Save the settings given: {@code setClerkLimit} the clerk limit (null: no limit), a non-null
714	     * {@code floor} the floor, a non-null {@code terms} the terms in days, a non-null {@code latePct} the
715	     * late percent, {@code setPolicyDate} the policy date (null: the sheet's today); each one saved is
716	     * audited, even when its value is the same. A floor, terms, late percent or policy date that moves
717	     * dues records the rollups that moved.
718	     */
719	    @Transactional
720	    public Sheet save(String sheetId, String user, boolean setClerkLimit, BigDecimal clerkLimit, BigDecimal floor,
721	            Integer terms, BigDecimal latePct, boolean setPolicyDate, LocalDate policyDate) {
722	        Sheet sheet = sheets.lock(sheetId, user);
723	        if (setClerkLimit) {
724	            sheet.setClerkLimit(clerkLimit);
725	            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
726	                    + " key=clerk-limit value=" + (clerkLimit == null ? "" : clerkLimit.toPlainString()));
727	        }
728	        if (floor != null) {
729	            RollupService.Rollup before = rollups.snapshot(sheetId);
730	            sheet.setFloor(floor);
731	            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
732	                    + " key=floor value=" + floor.toPlainString());
733	            rollups.recordChanges(sheetId, user, before);
734	        }
735	        if (terms != null) {
736	            RollupService.Rollup before = rollups.snapshot(sheetId);
737	            sheet.setTerms(terms);
738	            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
739	                    + " key=terms value=" + terms);
740	            rollups.recordChanges(sheetId, user, before);
741	        }
742	        if (latePct != null) {
743	            RollupService.Rollup before = rollups.snapshot(sheetId);
744	            sheet.setLatePct(latePct);
745	            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
746	                    + " key=late-pct value=" + latePct.toPlainString());
747	            rollups.recordChanges(sheetId, user, before);
748	        }
749	        if (setPolicyDate) {
750	            RollupService.Rollup before = rollups.snapshot(sheetId);
751	            sheet.setPolicyDate(policyDate);
752	            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
753	                    + " key=policy-date value=" + (policyDate == null ? "" : policyDate));
754	            rollups.recordChanges(sheetId, user, before);
755	        }
756	        return sheet;
757	    }
758	
759	    /** The roles the sheet gives user names, by name; a name not among them is a clerk. */
760	    @Transactional(readOnly = true)
761	    public List<SheetRole> roles(String sheetId) {
762	        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
763	    }
764	
765	    /** The role the sheet gives a user name; clerk when it gives none. */
766	    @Transactional(readOnly = true)
767	    public Role roleOf(String sheetId, String userName) {
768	        return roles.findBySheetIdAndUserName(sheetId, userName).map(SheetRole::getRole).orElse(Role.CLERK);
769	    }
770	
771	    /** Give a user name a role, replacing the one it had. */
772	    @Transactional
773	    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
774	        sheets.lock(sheetId, user);
775	        SheetRole entry = roles.findBySheetIdAndUserName(sheetId, userName)
776	                .orElseGet(() -> new SheetRole(sheetId, userName, role));
777	        entry.setRole(role);
778	        SheetRole saved = roles.saveAndFlush(entry);
779	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
780	                + " user=" + userName + " role=" + role.name().toLowerCase());
781	        return saved;
782	    }
783	}
