1019	@Service
1020	public class SheetService {
1021	
1022	    private final SheetRepository sheets;
1023	    private final RollupService rollups;
1024	
1025	    public SheetService(SheetRepository sheets, RollupService rollups) {
1026	        this.sheets = sheets;
1027	        this.rollups = rollups;
1028	    }
1029	
1030	    /** The sheet with this id; a sheet never loaded before is started empty, today at the real date. */
1031	    @Transactional
1032	    public Sheet load(String id, String user) {
1033	        return sheets.findById(id).orElseGet(() -> {
1034	            try {
1035	                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
1036	            } catch (DataIntegrityViolationException raced) {
1037	                return sheets.findById(id).orElseThrow(() -> raced);
1038	            }
1039	        });
1040	    }
1041	
1042	    /**
1043	     * The sheet's "today". Every decision that depends on the date, and every default date, uses
1044	     * this and never the real clock.
1045	     */
1046	    @Transactional(readOnly = true)
1047	    public LocalDate today(String id) {
1048	        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
1049	    }
1050	
1051	    /**
1052	     * Change the sheet's "today" (the sheet is started when it was never loaded before). It has no
1053	     * audit line of its own, but is followed by the rollup lines of the figures it moves.
1054	     */
1055	    @Transactional
1056	    public Sheet setToday(String id, String user, LocalDate today) {
1057	        Sheet sheet = lock(id, user);
1058	        RollupService.Rollup before = rollups.snapshot(id);
1059	        sheet.setToday(today);
1060	        sheets.flush();
1061	        rollups.recordChanges(id, user, before);
1062	        return sheet;
1063	    }
1064	
1065	    /**
1066	     * Lock the sheet until the current transaction ends, so its claims' statuses change one at a
1067	     * time (the sheet is started when it was never loaded before).
1068	     */
1069	    @Transactional
1070	    public Sheet lock(String id, String user) {
1071	        return sheets.findByIdForUpdate(id).orElseGet(() -> {
1072	            load(id, user);
1073	            return sheets.findByIdForUpdate(id).orElseThrow();
1074	        });
1075	    }
1076	}
