1199	import java.nio.charset.StandardCharsets;
1200	import java.nio.file.Files;
1201	import java.nio.file.Path;
1202	import java.nio.file.StandardOpenOption;
1203	import org.springframework.beans.factory.annotation.Value;
1204	import org.springframework.stereotype.Service;
1205	import org.springframework.transaction.support.TransactionSynchronization;
1206	import org.springframework.transaction.support.TransactionSynchronizationManager;
1207	
1208	/**
1209	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
1210	 * so tests can assert side-effects by reading that file — the second test-assertion channel
1211	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
1212	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
1213	 *
1214	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
1215	 * SYNC) so a test reads the record immediately.
1216	 */
1217	@Service
1218	public class Audit {
1219	
1220	    private final Path file;
1221	
1222	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
1223	        this.file = Path.of(path);
1224	    }
1225	
1226	    /** Append one audit record. Tests assert the exact line(s) in the file. */
1227	    public synchronized void record(String entry) {
1228	        try {
1229	            Path parent = file.toAbsolutePath().getParent();
1230	            if (parent != null) {
1231	                Files.createDirectories(parent);
1232	            }
1233	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
1234	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
1235	        } catch (IOException e) {
1236	            throw new UncheckedIOException(e);
1237	        }
1238	    }
1239	
1240	    /**
1241	     * Append one audit record once the current transaction commits, so a change that is refused or
1242	     * rolled back writes nothing. Without a transaction the record is appended at once.
1243	     */
1244	    public void recordOnCommit(String entry) {
1245	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
1246	            record(entry);
1247	            return;
1248	        }
1249	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
1250	            @Override
1251	            public void afterCommit() {
1252	                record(entry);
1253	            }
1254	        });
1255	    }
1256	
1257	    /** Truncate the audit file. */
1258	    public synchronized void clear() {
1259	        try {
1260	            Files.deleteIfExists(file);
1261	        } catch (IOException e) {
1262	            throw new UncheckedIOException(e);
1263	        }
1264	    }
1265	}
