9	// The due-totals the screen shows, worked out once so the people list, the periods list and the
10	// summary all agree.
11	@Injectable({ providedIn: 'root' })
12	export class TotalsService {
13	  private readonly people = inject(PeopleService);
14	  private readonly claims = inject(ClaimsService);
15	  private readonly periods = inject(PeriodsService);
16	  private readonly rates = inject(RatesService);
17	  private readonly settings = inject(SettingsService);
18	  private readonly sheets = inject(SheetService);
19	
20	  /**
21	   * Whether a claim's live figures round half up: it rounds by a date before the policy date in force
22	   * (the sheet's today when none is set); else they round half to even.
23	   */
24	  readonly halfUp = computed(() => {
25	    const policy = this.settings.policyInForce();
26	    const roundingDate = this.claims.roundingDate();
27	    return (c: Claim) => policy !== null && roundingDate(c) < policy;
28	  });
29	
30	  /**
31	   * Each person's due-total in cents: the sum of their open and settled claims' dues (those with one);
32	   * absent when the grade in force on today has no rate in force then and none of those claims has a due.
33	   */
34	  readonly personDueTotals = computed(() => {
35	    const out = new Map<number, number>();
36	    const floor = this.settings.floorCents();
37	    const late = this.settings.late();
38	    const halfUp = this.halfUp();
39	    for (const p of this.people.people()) {
40	      const counted = (this.claims.byPerson().get(p.id) ?? []).filter(this.claims.live());
41	      const rateOn = (date: string) => this.rateOn(p, date);
42	      const dues = counted.map((c) => claimDue(c, rateOn, floor, late, halfUp));
43	      const grade = this.gradeToday(p);
44	      if (!(grade && this.rates.byGrade().has(grade)) && dues.every((d) => d === undefined)) continue;
45	      out.set(p.id, dues.reduce<number>((sum, d) => sum + (d ?? 0), 0));
46	    }
47	    return out;
48	  });
49	
50	  /** Each open period's live due-total in cents, by period id: the dues of the counting claims dated in it. */
51	  private readonly livePeriodTotals = computed(() => {
52	    const people = new Map(this.people.people().map((p) => [p.id, p]));
53	    const out = new Map<number, number>();
54	    const floor = this.settings.floorCents();
55	    const late = this.settings.late();
56	    const halfUp = this.halfUp();
57	    for (const c of this.claims.claims().filter(this.claims.live())) {
58	      const period = this.periods.periodOn(c.date);
59	      const p = people.get(c.personId);
60	      if (!period || !p) continue;
61	      const d = claimDue(c, (date) => this.rateOn(p, date), floor, late, halfUp);
62	      out.set(period.id, (out.get(period.id) ?? 0) + (d ?? 0));
63	    }
64	    return out;
65	  });
66	
67	  /** Each period's due-total as shown, by period id: the one fixed when it closed, else the live one. */
68	  readonly periodDueTotals = computed(() => {
69	    const live = this.livePeriodTotals();
70	    return new Map(this.periods.periods().map((p) => [
71	      p.id,
72	      p.closed ? (p.closedTotal ?? '') : money(live.get(p.id) ?? 0),
73	    ]));
74	  });
