76	  /** The grade in force on the sheet's today. */
77	  gradeToday(p: Person): Grade | undefined {
78	    const today = this.sheets.today();
79	    return today === null ? p.grade : gradeOn(p.grades, today);
80	  }
81	
82	  /** The rate in force on a date for the person's grade in force then, in hundredths of a percent. */
83	  rateOn(p: Person, date: string): number | undefined {
84	    const grade = gradeOn(p.grades, date);
85	    return grade && this.rates.rateOn(grade, date);
86	  }
87	}
