96	export interface Claim {
97	  id: number;
98	  personId: number;
99	  /** Text with two decimals, e.g. "10.00". */
100	  amount: string;
101	  /** yyyy-MM-dd */
102	  date: string;
103	  note: string;
104	  status: ClaimStatus;
105	  /** Given when opened; null while a draft and once voided. */
106	  number: number | null;
107	  /** A settled claim's due, fixed when it was settled, as text with two decimals; null while live, or when its grade had no rate then (it then follows the rates). */
108	  due: string | null;
109	  /** The user who opened it; null while a draft. They may not settle it. */
110	  openedBy: string | null;
111	  /** Bound by its person's last statement: it shows and totals `statedDue` until the next one. */
112	  stated: boolean;
113	  /** The figure it had at that statement, as text with two decimals; null when it had none (n/a). */
114	  statedDue: string | null;
115	  /** A correction's (negative amount) number of the settled claim of the same person it corrects; null otherwise. */
116	  corrects: number | null;
117	}
118	
119	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
120	
121	/** A change of status a claim's buttons ask for. */
122	export type ClaimAction = 'open' | 'settle' | 'void';
123	
124	/** Only open and settled claims count toward claimed and due; drafts and voided claims do not. */
125	export function counts(c: Claim): boolean {
126	  return c.status === 'OPEN' || c.status === 'SETTLED';
127	}
128	
129	/** A claim keeps a figure that does not follow the rates: settled with a fixed due, or bound by a statement to one (not n/a). */
130	export function fixed(c: Claim): boolean {
131	  return c.due !== null || (c.stated && c.statedDue !== null);
132	}
133	
134	/** What an overdue claim's late charge follows: the terms (days), the sheet's today (yyyy-MM-dd; null: none loaded) and the late percent (in hundredths of a percent). */
135	export interface LateTerms {
136	  terms: number;
137	  today: string | null;
138	  pct: number;
139	}
140	
141	/**
142	 * A claim's due in cents: a settled claim's fixed figure (any late charge frozen in), else the figure
143	 * its person's last statement bound it to, otherwise its amount times the rate in force on its date
144	 * (looked up by `rateOn`, in hundredths of a percent), raised to the sheet's floor (in cents) unless a correction;
145	 * undefined when it has none. An overdue claim's figure gains its late charge on top (never bound).
146	 * Its live figures round half up when `halfUp` says so for it, else half to even.
147	 */
148	export function claimDue(
149	  c: Claim, rateOn: (date: string) => number | undefined, floor: number, late?: LateTerms,
150	  halfUp: (c: Claim) => boolean = () => false,
151	): number | undefined {
152	  if (c.due !== null) return cents(c.due);
153	  const up = halfUp(c);
154	  const figure = baseDue(c, rateOn, floor, up);
155	  return figure === undefined || !late || correction(c) ? figure : figure + lateCharge(c, figure, late, up);
156	}
157	
158	function baseDue(
159	  c: Claim, rateOn: (date: string) => number | undefined, floor: number, halfUp: boolean,
160	): number | undefined {
161	  if (c.stated) return c.statedDue === null ? undefined : cents(c.statedDue);
162	  const rate = rateOn(c.date);
163	  if (rate === undefined) return undefined;
164	  const d = due(cents(c.amount), rate, halfUp);
165	  return correction(c) ? d : Math.max(d, floor);
166	}
167	
168	/** A correction: a negative amount; its due has no floor and no late charge. */
169	export function correction(c: Claim): boolean {
170	  return c.amount.startsWith('-');
171	}
172	
173	/** The late charge in cents on a figure: the late percent of it for every full 30 days the claim is overdue, rounded like due. */
174	export function lateCharge(c: Claim, figure: number, late: LateTerms, halfUp = false): number {
175	  if (late.today === null || !overdue(c, late.terms, late.today)) return 0;
176	  const days = (Date.parse(late.today) - Date.parse(dueBy(c, late.terms))) / 86_400_000;
177	  return due(figure, late.pct * Math.floor(days / 30), halfUp);
178	}
179	
180	/** The date (yyyy-MM-dd) a claim is due by: its date plus the terms (days). */
181	export function dueBy(c: Claim, terms: number): string {
182	  const [y, m, d] = c.date.split('-').map(Number);
183	  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
184	}
185	
186	/** A claim is overdue when it is open and its due-by is before the sheet's today (yyyy-MM-dd; null: none loaded). */
187	export function overdue(c: Claim, terms: number, today: string | null): boolean {
188	  return today !== null && c.status === 'OPEN' && dueBy(c, terms) < today;
189	}
