321	/** "12.34" as 1234. */
322	export function cents(amount: string): number {
323	  const negative = amount.startsWith('-');
324	  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
325	  const out = Number(whole) * 100 + Number((frac + '00').slice(0, 2));
326	  return negative ? -out : out;
327	}
