77	            <th scope="col">Patrons</th><th scope="col">Backing</th>
78	            <th scope="col"><span class="visually-hidden">Actions</span></th><th scope="col">Claims</th>
79	          </tr>
80	        </thead>
81	        <tbody>
82	          @for (p of listed(); track p.id) {
83	            <tr [attr.data-testid]="'person-row-' + p.id">
