90	              <td data-testid="person-statement-date">{{ p.statementDate ?? '' }}</td>
91	              <td data-testid="person-retired">{{ p.retiredFrom ? 'yes' : 'no' }}</td>
92	              <td data-testid="person-retired-from">{{ p.retiredFrom ?? '' }}</td>
93	              <td data-testid="person-hold">{{ p.held ? 'yes' : 'no' }}</td>
94	              <td data-testid="person-overdue-count">{{ overdueOf(p.id).count }}</td>
95	              <td data-testid="person-overdue-total">{{ money(overdueOf(p.id).cents) }}</td>
96	              <td data-testid="person-patrons">{{ patronNames(p) }}</td>
97	              <td data-testid="person-backing">{{ money(backing(p)) }}</td>
98	              <td>
99	                <button type="button" [attr.data-testid]="'person-edit-' + p.id" (click)="open(p)"
100	                  [attr.aria-label]="'Edit ' + p.name">Edit</button>
101	                <button type="button" data-testid="person-statement" (click)="statement(p)"
102	                  [attr.aria-label]="'Take a statement for ' + p.name">Statement</button>
103	                <label [for]="'person-retire-date-' + p.id">Retire from</label>
104	                <input type="date" [id]="'person-retire-date-' + p.id" data-testid="person-retire-date"
105	                  #retireDate (input)="setRowError(p.id, '')" />
106	                <button type="button" data-testid="person-retire" (click)="retire(p, retireDate.value)"
107	                  [attr.aria-label]="'Retire ' + p.name">Retire</button>
108	                <button type="button" data-testid="person-hold-toggle" (click)="toggleHold(p)"
109	                  [attr.aria-label]="(p.held ? 'Release ' : 'Hold ') + p.name">{{ p.held ? 'Release' : 'Hold' }}</button>
110	                <label [for]="'person-patron-select-' + p.id">Patron</label>
111	                <select [id]="'person-patron-select-' + p.id" data-testid="person-patron-select" #patron
112	                  (change)="setRowError(p.id, '')">
113	                  <option value="">Choose a patron</option>
114	                  @for (o of people.people(); track o.id) {
115	                    @if (o.id !== p.id) {
